  B.rueckenmark = O('rueckenmark', line([[200, 104], [200, 200], [200, 330], [200, 420]], 'c-cord') + [430, 444, 458, 472].map((y, i) => line([[200, 420], [196 - i * 2, y]], 'c-cauda') + line([[200, 420], [204 + i * 2, y]], 'c-cauda')).join(''));
  B.nerven = O('nerven', NRV.map(p => line(p, 'c-nerve')).join('') + [220, 250, 280, 310, 340].map(y => line([[200, y], [176, y + 6], [146, y + 18]], 'c-nerve-s') + line([[200, y], [224, y + 6], [254, y + 18]], 'c-nerve-s')).join(''));
