  const bone = (a, b, w) => `<path d="M${a[0]} ${a[1]}L${b[0]} ${b[1]}" class="c-bone" style="stroke-width:${w}"/><circle cx="${a[0]}" cy="${a[1]}" r="${w * .75}" class="c-bone-e"/><circle cx="${b[0]}" cy="${b[1]}" r="${w * .75}" class="c-bone-e"/>`;
